session_start();if(!isset($_SESSION['student_id'])){header('Location: index.php');exit;}require 'Includes/dbcon.php';$stmt=$con->prepare('SELECT id,question,option_a,option_b,option_c,option_d,correct_option FROM questions ORDER BY id ASC');$stmt->execute();$res=$stmt->get_result();$pageTitle='Answer Review | FountainTest';include 'Includes/header.php';?>
<div class="mb-4"><span class="eyebrow">Study centre</span><h1 class="h2 mt-2">Answer review</h1><p class="muted">Use these explanations-free answer keys to review the question bank for practice.</p></div><?php $n=0;while($q=$res->fetch_assoc()):$n++;?><article class="question-card"><div class="question-number">Question <?=$n?></div><p class="question-text"><?=nl2br(htmlspecialchars($q['question']))?></p><div class="row g-2"><?php foreach(['A'=>'option_a','B'=>'option_b','C'=>'option_c','D'=>'option_d'] as $letter=>$field):if(trim((string)$q[$field])==='')continue;?><div class="col-md-6"><div class="answer-option mb-0 <?=($q['correct_option']===$letter?'border-success':'')?>"><span class="fw-bold"><?=$letter?>.</span><span><?=htmlspecialchars($q[$field])?><?php if($q['correct_option']===$letter):?><span class="d-block text-success small fw-bold mt-1">Correct answer</span><?php endif;?></span></div></div><?php endforeach;?></div></article><?php endwhile;?><a class="btn btn-outline-success" href="dashboard.php">← Back to dashboard</a><?php include 'Includes/footer.php';?>
